solution.solution.cpp:
#include <array>

int daysIn(int month)
{
    constexpr std::array<int, 12> table{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month < 1 || month > 12)
    {
        return -1;
    }
    return table[static_cast<std::size_t>(month - 1)];
}

unitTests:
TEST("some months") { CHECK_EQ(daysIn(1), 31); CHECK_EQ(daysIn(2), 28); CHECK_EQ(daysIn(4), 30); CHECK_EQ(daysIn(12), 31); }
TEST("a whole year") { int total{ 0 }; for (int m{ 1 }; m <= 12; ++m) total += daysIn(m); CHECK_EQ(total, 365); }
TEST("out of range") { CHECK_EQ(daysIn(0), -1); CHECK_EQ(daysIn(13), -1); }

